def __build_font(name):
    try:
        f = getattr(_lib_lvgl.lib, name)
        f_pointer = _lib_lvgl.ffi.addressof(f)

        instance = font_t()
        instance._obj = f_pointer
        return instance

    except AttributeError:
        class dummy_class:

            @property
            def _obj(self):
                raise RuntimeError(
                    'LVGL was not compiled with this font ("{0}"'.format(name)
                )

        return dummy_class()


